INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('line-obstacle-step-1', 'line-obstacle', 1, 'Gắn khung và truyền động', 'Gắn hai động cơ, bánh xe và bánh tự do vào khung xe.', '{}');
INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('line-obstacle-step-2', 'line-obstacle', 2, 'Cố định bo mạch', 'Cố định Arduino Uno và L298N, chừa khoảng trống phía trước cho cảm biến.', '{}');
INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('line-obstacle-step-3', 'line-obstacle', 3, 'Gắn hai loại cảm biến', 'Gắn hai cảm biến dò line ở mặt dưới phía trước và HC-SR04 hướng về phía trước.', '{}');
INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('line-obstacle-step-4', 'line-obstacle', 4, 'Nối dây tín hiệu và nguồn', 'Đấu L298N vào D5–D10, cảm biến line vào D2/D3, HC-SR04 vào D11/D12; nối chung GND.', '{}');
INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('line-obstacle-step-5', 'line-obstacle', 5, 'Nạp chương trình và thử', 'Nạp chương trình ưu tiên dừng/né khi vật cản gần, sau đó dò lại vạch; thử ở tốc độ thấp.', '{}');
INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('servo-scout-step-1', 'servo-scout', 1, 'Gắn khung và truyền động', 'Lắp hai động cơ, bánh xe và bánh tự do vào khung xe.', '{}');
INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('servo-scout-step-2', 'servo-scout', 2, 'Cố định bo mạch và nguồn', 'Cố định Arduino, L298N, hộp pin và module DC-DC ở vị trí chắc chắn.', '{}');
INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('servo-scout-step-3', 'servo-scout', 3, 'Lắp cụm servo quét', 'Gắn servo SG90 ở đầu xe, lắp giá đỡ HC-SR04 lên càng servo và hướng hai mắt cảm biến ra trước.', '{}');
INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('servo-scout-step-4', 'servo-scout', 4, 'Đấu nối có kiểm tra điện áp', 'Đấu L298N vào D5–D10, servo vào D3, TRIG/ECHO vào D11/D12. Bản lắp thực tế cần nguồn bàn DC 9V đủ dòng cấp cho VIN/DC jack Arduino và XL4015; hộp pin 4AA 6V chỉ cấp L298N Vs. Đo XL4015 đúng 5.0V rồi mới nối riêng SG90; cấp HC-SR04 và logic L298N từ Arduino 5V, kiểm tra jumper theo đúng module và nối chung GND.', '{}');
INSERT IGNORE INTO assembly_steps (`id`, `robot_id`, `step_order`, `title`, `instruction`, `illustration`) VALUES ('servo-scout-step-5', 'servo-scout', 5, 'Nạp chương trình và thử', 'Nạp chương trình quét các góc trái/giữa/phải, chờ servo ổn định rồi đo; thử né vật cản ở tốc độ thấp.', '{}');
